    int var1 = 5;
    int var2 = 10;
    int var3 = 15;

    for (const char* name : {"var1", "var2", "var3"}) {
        std::cout << name << " = " << *(reinterpret_cast<int*>((&var1 + (std::string(name).at(0) - 'a')))) << std::endl;
    }

    return 0;
}
